دالة عدّ_الكلمات(نص) {
    متغير عد = ٠
    إذا (نص != "") {
        من_أجل (ي من ٠ إلى طول(نص) - ١) {
            إذا (نص[ي] == " ") {
                عد = عد + ١
            }
        }
        عد = عد + ١
    }
    ارجع عد
}
```

